// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, uint256 n, address actor) public {
        vm.assume(t > 1);
        vm.assume(actor != address(c) && actor != address(this));
        vm.warp(t);
        vm.roll(bound(n, 0, block.number + type(uint16).max));
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        // Rule: a successful call must store exactly the current block timestamp.
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}
